115	        if (owner.getRegistrationDate() == null) {
116	            owner.setRegistrationDate(java.time.LocalDate.now());
117	        }
118	        // Reject creating an owner whose normalized telephone is already used by another owner.
119	        if (isTelephoneInUse(normalizedTelephone)) {
120	            throw new DuplicateTelephoneException(
121	                "An owner with telephone " + normalizedTelephone + " already exists");
122	        }
123	        this.clinicService.saveOwner(owner);
124	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
125	        headers.setLocation(UriComponentsBuilder.newInstance()
126	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
